from __future__ import unicode_literals

from ..raml.xml import Xml


class Param(Xml):

    @property
    def name(self):
        """Name of this parameter"""
        return self.xml.get('name') or self.xml.getparent().get('name')

    @property
    def value(self):
        """Value of this parameter"""
        return self.xml.text

    @value.setter
    def value(self, new_value):
        """Value of this parameter"""
        self.xml.text = str(new_value)
